#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v;
    long long weight;
} Edge;

static int *dsu;
static int *dsu_size;

static int find_root(int x) {
    if (dsu[x] != x) {
        dsu[x] = find_root(dsu[x]);
    }
    return dsu[x];
}

static int compare_edges(const void *a, const void *b) {
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    if (ea->weight < eb->weight) return -1;
    if (ea->weight > eb->weight) return 1;
    return 0;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int cells = n * m;
    long long *power = (long long *)malloc((size_t)cells * sizeof(long long));
    for (int i = 0; i < cells; i++) {
        scanf("%lld", &power[i]);
    }

    int edge_count = 0;
    Edge *edges = (Edge *)malloc((size_t)(2 * cells + 1) * sizeof(Edge));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int u = i * m + j;
            if (j + 1 < m) {
                int v = u + 1;
                edges[edge_count++] = (Edge){u, v,
                    power[u] > power[v] ? power[u] : power[v]};
            }
            if (i + 1 < n) {
                int v = u + m;
                edges[edge_count++] = (Edge){u, v,
                    power[u] > power[v] ? power[u] : power[v]};
            }
        }
    }

    qsort(edges, edge_count, sizeof(Edge), compare_edges);

    int capacity = 2 * cells;
    int *representative = (int *)malloc((size_t)cells * sizeof(int));
    dsu = (int *)malloc((size_t)cells * sizeof(int));
    dsu_size = (int *)malloc((size_t)cells * sizeof(int));

    long long *label = (long long *)malloc((size_t)capacity * sizeof(long long));
    long long *total = (long long *)malloc((size_t)capacity * sizeof(long long));
    int *parent = (int *)malloc((size_t)capacity * sizeof(int));

    for (int i = 0; i < cells; i++) {
        dsu[i] = i;
        dsu_size[i] = 1;
        representative[i] = i;
        label[i] = power[i];
        total[i] = power[i];
        parent[i] = -1;
    }

    int node_count = cells;

    for (int i = 0; i < edge_count; i++) {
        int ru = find_root(edges[i].u);
        int rv = find_root(edges[i].v);
        if (ru == rv) continue;

        int left = representative[ru];
        int right = representative[rv];
        int new_node = node_count++;

        label[new_node] = edges[i].weight;
        total[new_node] = total[left] + total[right];
        parent[left] = new_node;
        parent[right] = new_node;

        if (dsu_size[ru] < dsu_size[rv]) {
            int temp = ru;
            ru = rv;
            rv = temp;
        }
        dsu[rv] = ru;
        dsu_size[ru] += dsu_size[rv];
        representative[ru] = new_node;
    }

    for (int i = 0; i < cells; i++) {
        if (find_root(i) == i) {
            parent[representative[i]] = representative[i];
        }
    }

    int levels = 1;
    while ((1LL << levels) <= node_count) levels++;

    int *up = (int *)malloc((size_t)levels * node_count * sizeof(int));
    for (int i = 0; i < node_count; i++) {
        up[i] = parent[i];
    }
    for (int k = 1; k < levels; k++) {
        int *previous = up + (size_t)(k - 1) * node_count;
        int *current = up + (size_t)k * node_count;
        for (int i = 0; i < node_count; i++) {
            current[i] = previous[previous[i]];
        }
    }

    int *base = (int *)malloc((size_t)cells * sizeof(int));
    for (int i = 0; i < cells; i++) {
        int u = i;
        for (int k = levels - 1; k >= 0; k--) {
            int ancestor = up[(size_t)k * node_count + u];
            if (label[ancestor] <= power[i]) {
                u = ancestor;
            }
        }
        base[i] = u;
    }

    int *next = (int *)malloc((size_t)node_count * sizeof(int));
    for (int i = 0; i < node_count; i++) {
        int u = i;
        for (int k = levels - 1; k >= 0; k--) {
            int ancestor = up[(size_t)k * node_count + u];
            if (label[ancestor] <= total[i]) {
                u = ancestor;
            }
        }
        next[i] = u;
    }

    free(up);
    free(parent);
    free(representative);
    free(dsu);
    free(dsu_size);
    free(edges);

    int *jump = (int *)malloc((size_t)levels * node_count * sizeof(int));
    for (int i = 0; i < node_count; i++) {
        jump[i] = next[i];
    }
    for (int k = 1; k < levels; k++) {
        int *previous = jump + (size_t)(k - 1) * node_count;
        int *current = jump + (size_t)k * node_count;
        for (int i = 0; i < node_count; i++) {
            current[i] = previous[previous[i]];
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int u = base[i * m + j];
            for (int k = levels - 1; k >= 0; k--) {
                u = jump[(size_t)k * node_count + u];
            }
            if (j > 0) printf(" ");
            printf("%lld", total[u]);
        }
        printf("\n");
    }

    free(power);
    free(label);
    free(total);
    free(base);
    free(next);
    free(jump);

    return 0;
}
